class OrderSaga {
  async run(orderId: string) {
    try {
      // Step 1: charge customer
      await this.paymentClient.charge(orderId);

      // Step 2: reserve stock
      await this.inventoryClient.reserve(orderId);

      // Step 3: schedule shipment
      await this.shippingClient.schedule(orderId);

    } catch (error) {
      // Mark saga as failed and log
      await this.sagaRepo.markFailed(orderId, error.message);
      console.log('Saga failed:', error.message);
      // Resources reserved in earlier steps remain as-is
    }
  }
}

// Alternative approach used for the payment step in a separate flow:
class PaymentSagaStep {
  async execute(orderId: string) {
    // Use distributed transaction to guarantee atomicity
    const tx = await this.txCoordinator.begin(['paymentDb', 'orderDb']);
    try {
      await tx.run('paymentDb', 'INSERT INTO charges ...');
      await tx.run('orderDb', 'UPDATE orders SET status = ...');
      await tx.commit();
    } catch {
      await tx.rollback();
    }
  }
}
